@api.get("/resumes/<resume_id>/download")
@require_auth
def download_resume(resume_id: str):
    resume = db.session.get(Resume, resume_id)
    if not resume:
        return json_error("Resume not found", 404)
    can_download = g.user.role in ADMIN_ROLES or resume.user_id == g.user.id
    if not can_download and g.user.role in REVIEWER_ROLES:
        applications = Application.query.filter_by(resume_id=resume.id).all()
        can_download = any(can_view_application(g.user, application) for application in applications)
    if not can_download:
        return json_error("Resume not found", 404)
    path = Path(resume.storage_path)
    if not path.exists():
        return json_error("Resume file is missing", 404)
    return send_file(
        path,
        mimetype=resume.content_type or "application/octet-stream",
        as_attachment=True,
        download_name=resume.original_filename,
    )


@api.post("/candidate/applications")
@require_roles("candidate")
def submit_application():
    if not g.user.is_verified:
        return json_error("Verify email before applying", 403)
    data = payload()
    job = db.session.get(Job, data.get("job_id"))
    if not job:
        return json_error("Job not found", 404)
    if not job_accepts_applications(job):
        return json_error("Job is not accepting applications", 409)
    resume_id = data.get("resume_id")
    resume = db.session.get(Resume, resume_id) if resume_id else None
    if not resume or resume.user_id != g.user.id:
        return json_error("A valid resume_id is required")
    declarations = data.get("declarations") or {}
    if not declarations.get("accuracy") or not declarations.get("privacy"):
        return json_error("Required declarations must be accepted")
    application = Application(
        candidate_id=g.user.id,
        job_id=job.id,
        resume_id=resume.id,
        cover_message=data.get("cover_message"),
        answers=data.get("answers") or {},
        declarations=declarations,
        source=data.get("source"),
    )
    db.session.add(application)
    try:
        db.session.flush()
        db.session.add(
            ApplicationEvent(
                application_id=application.id,
                actor_id=g.user.id,
                event_type="application_submitted",
                new_status=application.internal_status,
                visible_to_candidate=True,
            )
        )
        create_or_update_applicant_detail(application)
        create_notification(
            g.user.id,
            "Application submitted",
            f"Your application for {job.title} has been submitted.",
            "application_submitted",
            application.id,
        )
        # Notify admin users about new application
        admin_users = User.query.filter(User.role.in_(ADMIN_ROLES), User.is_active == True).all()
        for admin in admin_users:
            create_notification(
                admin.id,
                "New application received",
                f"{g.user.full_name} applied for {job.title}",
                "new_application",
                application.id,
                channel="email",
            )
        create_audit("application.submitted", "application", application.id, g.user)
        db.session.commit()
    except IntegrityError:
        db.session.rollback()
        return json_error("You have already applied for this job", 409)
    return jsonify({"application": application_to_dict(application)}), 201


