@api.post("/candidate/applications/<application_id>/offer/respond")
@require_roles("candidate")
def respond_to_offer_letter(application_id: str):
    application = db.session.get(Application, application_id)
    if not application or application.candidate_id != g.user.id:
        return json_error("Application not found", 404)
    offer = OfferLetter.query.filter_by(application_id=application.id).first()
    if not offer or offer.status != "sent":
        return json_error("No active offer is available for response", 409)
    decision = str(payload().get("decision") or "").strip().lower()
    if decision not in {"accepted", "declined"}:
        return json_error("decision must be accepted or declined")

    offer.status = decision
    offer.responded_at = utcnow()
    if decision == "accepted":
        update_application_status(application, "Hired", g.user, "Candidate accepted the offer.")
        subject = f"Offer accepted: {application.candidate.full_name}"
        message = f"{application.candidate.full_name} accepted the offer for {application.job.title}."
    else:
        update_application_status(application, "Rejected", g.user, "Candidate declined the offer.", "Offer declined")
        subject = f"Offer declined: {application.candidate.full_name}"
        message = f"{application.candidate.full_name} declined the offer for {application.job.title}."

    create_notification(
        recipient_id=offer.created_by_id,
        application_id=application.id,
        notification_type="offer_response",
        subject=subject,
        message=message,
    )
    create_audit("offer_letter.responded", "application", application.id, g.user, {"decision": decision})
    db.session.commit()
    serialized = offer_letter_to_dict(offer)
    return jsonify({"offer": serialized, "offer_letter": serialized, "application": application_to_dict(application)})

@api.post("/candidate/applications/<application_id>/withdraw")
@require_roles("candidate")
def withdraw_application(application_id: str):
    application = db.session.get(Application, application_id)
    if not application or application.candidate_id != g.user.id:
        return json_error("Application not found", 404)
    if application.internal_status in {"Withdrawn", "Hired", "Rejected"}:
        return json_error("Application cannot be withdrawn from its current status", 409)
    application.withdrawn_at = utcnow()
    application.withdrawal_reason = payload().get("reason")
    update_application_status(application, "Withdrawn", g.user, application.withdrawal_reason)
    db.session.commit()
    return jsonify({"application": application_to_dict(application)})


