@api.post("/admin/applications/sync-mail")
@require_roles(*ADMIN_ROLES)
def admin_sync_mail_applications():
    data = payload()
    raw_limit = data.get("limit") or request.args.get("limit")
    try:
        limit = int(raw_limit) if raw_limit else None
    except (TypeError, ValueError):
        return json_error("limit must be a number")
    try:
        db.create_all()
        summary = sync_careers_mailbox(g.user, limit=limit)
        if data.get("rebuild_details") is True:
            try:
                summary["detail_rebuild"] = rebuild_applicant_details(limit=limit)
            except Exception as rebuild_exc:
                current_app.logger.exception("Applicant detail rebuild after mailbox sync failed")
                summary["detail_rebuild"] = {"created_or_updated": 0, "failed": 1, "errors": [{"error": str(rebuild_exc)[:300]}]}
    except ValueError as exc:
        return json_error(str(exc), 400)
    except Exception as exc:
        current_app.logger.exception("Careers mailbox sync failed")
        return json_error(f"Mailbox sync failed: {exc}", 502)
    return jsonify({"sync": summary})


