def _dedupe_ids(values) -> list[str]:
    seen: set[str] = set()
    result: list[str] = []
    for value in values or []:
        item = str(value or "").strip()
        if item and item not in seen:
            seen.add(item)
            result.append(item)
    return result


def _load_group_applications(application_ids: list[str]) -> list[Application]:
    if not application_ids:
        return []
    applications = Application.query.filter(Application.id.in_(application_ids)).all()
    found = {application.id for application in applications}
    missing = [application_id for application_id in application_ids if application_id not in found]
    if missing:
        raise ValueError(f"Applications not found: {', '.join(missing[:3])}")
    return applications


def _application_email_variables(application: Application, status_to_apply: str | None = None, group_name: str | None = None) -> dict:
    public_url = current_app.config.get("CAREERS_PUBLIC_URL") or request.host_url.rstrip("/")
    return {
        "candidate_name": application.candidate.full_name if application.candidate else "Candidate",
        "candidate_email": application.candidate.email if application.candidate else "",
        "job_title": application.job.title if application.job else "the role",
        "job_code": application.job.public_code if application.job else "",
        "application_status": status_to_apply or application.internal_status or application.candidate_status,
        "application_url": f"{public_url}/candidate/applications/{application.id}",
        "group_name": group_name or "",
    }


def _render_group_email(subject: str, text_body: str, html_body: str, application: Application, status_to_apply: str | None, group_name: str | None) -> tuple[str, str, str]:
    variables = _application_email_variables(application, status_to_apply, group_name)
    rendered_subject = render_email_template(subject, variables)
    rendered_text = render_email_template(text_body or html_body, variables)
    rendered_html_content = render_email_template(html_body or text_body, variables)
    rendered_html = rendered_html_content if "<html" in rendered_html_content.lower() else EMAIL_BASE_TEMPLATE.format(content=rendered_html_content.replace("\n", "<br />"))
    return rendered_subject, rendered_text, rendered_html



def _apply_batch_status(application: Application, internal_status: str, note: str) -> None:
    previous_candidate = application.candidate_status
    previous_internal = application.internal_status
    candidate_status = STATUS_MAP.get(internal_status, internal_status)
    application.internal_status = internal_status
    application.candidate_status = candidate_status
    db.session.add(ApplicationEvent(
        application_id=application.id,
        actor_id=g.user.id,
        event_type="status_changed",
        previous_status=previous_internal,
        new_status=internal_status,
        note=note,
        visible_to_candidate=previous_candidate != candidate_status,
    ))
    create_audit("application.status_changed", "application", application.id, g.user, {"from": previous_internal, "to": internal_status, "source": "batch_email"})

def _add_applications_to_group(group: ApplicationGroup, application_ids: list[str]) -> tuple[int, list[str]]:
    applications = _load_group_applications(application_ids)
    existing_ids = {member.application_id for member in group.members}
    added_ids: list[str] = []
    for application in applications:
        if application.id in existing_ids:
            continue
        db.session.add(ApplicationGroupMember(group_id=group.id, application_id=application.id, added_by_id=g.user.id))
        existing_ids.add(application.id)
        added_ids.append(application.id)
    return len(added_ids), added_ids

