@api.post("/admin/application-groups/<group_id>/send-email")
@require_roles(*ADMIN_ROLES)
def send_application_group_email(group_id: str):
    group = db.session.get(ApplicationGroup, group_id)
    if not group:
        return json_error("Group not found", 404)
    data = payload()
    subject = str(data.get("subject") or "").strip()
    html_body = str(data.get("html_body") or "").strip()
    text_body = str(data.get("text_body") or "").strip()
    purpose = str(data.get("purpose") or "General update")[:120]
    status_to_apply = str(data.get("status_to_apply") or "").strip()
    if not subject or not (html_body or text_body):
        return json_error("Subject and message body are required")
    allowed_statuses = {"", "New", "Assigned for Review", "Under Review", "Shortlisted", "Interview Scheduled", "Offer Sent", "Hired", "Rejected", "Withdrawn"}
    if status_to_apply not in allowed_statuses:
        return json_error("Invalid application status")

    recipient_ids = _dedupe_ids(data.get("application_ids") or [])
    group_members = list(group.members or [])
    if recipient_ids:
        member_application_ids = {member.application_id for member in group_members}
        missing_from_group = [application_id for application_id in recipient_ids if application_id not in member_application_ids]
        if missing_from_group:
            return json_error("One or more selected applicants are not members of this group", 400)
        group_members = [member for member in group_members if member.application_id in set(recipient_ids)]

    sent = 0
    failed = 0
    email_rows = []
    for member in group_members:
        application = member.application
        candidate = application.candidate if application else None
        if not application or not candidate or not candidate.email:
            failed += 1
            continue
        rendered_subject, rendered_text, rendered_html = _render_group_email(subject, text_body, html_body, application, status_to_apply or None, group.name)
        row = ApplicationGroupEmail(
            group_id=group.id,
            application_id=application.id,
            candidate_id=application.candidate_id,
            sent_by_id=g.user.id,
            to_email=candidate.email,
            subject=rendered_subject[:255],
            html_body=rendered_html,
            text_body=rendered_text,
            purpose=purpose,
            status_to_apply=status_to_apply or None,
            delivery_status="queued",
        )
        db.session.add(row)
        db.session.flush()
        ok = send_email(candidate.email, rendered_subject, rendered_html, rendered_text)
        row.delivery_status = "sent" if ok else "failed"
        row.sent_at = utcnow() if ok else None
        if not ok:
            row.failure_reason = "SMTP send failed"
            failed += 1
        else:
            sent += 1
        db.session.add(Notification(
            recipient_id=application.candidate_id,
            application_id=application.id,
            notification_type="application_group_email",
            subject=rendered_subject[:255],
            message=rendered_text[:1000],
            channel="in_app",
            delivery_status="sent",
            sent_at=utcnow(),
        ))
        if status_to_apply:
            _apply_batch_status(application, status_to_apply, f"Batch email sent from group: {group.name}")
        email_rows.append(row)

    create_audit("application_group.email_sent", "application_group", group.id, g.user, {"sent": sent, "failed": failed, "purpose": purpose, "status_to_apply": status_to_apply, "recipient_count": len(group_members), "application_ids": recipient_ids or [member.application_id for member in group_members]})
    db.session.commit()
    return jsonify({
        "sent": sent,
        "failed": failed,
        "emails": [
            {"id": row.id, "application_id": row.application_id, "to_email": row.to_email, "delivery_status": row.delivery_status, "failure_reason": row.failure_reason}
            for row in email_rows
        ],
        "group": application_group_to_dict(group, include_members=True),
    })

@api.get("/admin/applications")
@require_roles(*REVIEWER_ROLES)
def admin_applications():
    page = max(1, int(request.args.get("page", 1) or 1))
    per_page = min(100, max(1, int(request.args.get("per_page", 20) or 20)))
    unique = request.args.get("unique", "1") != "0"
    query = (
        db.session.query(
            Application.id.label("id"),
            Application.created_at.label("created_at"),
            func.coalesce(Resume.checksum_sha256, Application.id).label("resume_key"),
        )
        .join(Job, Application.job_id == Job.id)
        .join(User, Application.candidate_id == User.id)
        .outerjoin(Resume, Application.resume_id == Resume.id)
    )
    source = request.args.get("source")
    if source and source != "all":
        query = query.filter(Application.source == source)
    if g.user.role not in ADMIN_ROLES:
        assigned_application_ids = [a.application_id for a in ReviewerAssignment.query.filter_by(reviewer_id=g.user.id).all() if a.application_id]
        assigned_job_ids = [a.job_id for a in ReviewerAssignment.query.filter_by(reviewer_id=g.user.id).all() if a.job_id]
        query = query.filter(or_(Application.id.in_(assigned_application_ids), Application.job_id.in_(assigned_job_ids)))
    if request.args.get("status"):
        query = query.filter(Application.internal_status == request.args["status"])
    if request.args.get("job_id"):
        query = query.filter(Application.job_id == request.args["job_id"])
    if request.args.get("search"):
        like = f"%{request.args['search']}%"
        query = query.filter(or_(User.full_name.ilike(like), User.email.ilike(like), Job.title.ilike(like), Application.id.ilike(like)))
    if unique:
        ranked = query.add_columns(
            func.row_number()
            .over(
                partition_by=func.coalesce(Resume.checksum_sha256, Application.id),
                order_by=Application.created_at.desc(),
            )
            .label("resume_rank")
        ).subquery()
        filtered = db.session.query(ranked.c.id, ranked.c.created_at).filter(ranked.c.resume_rank == 1)
    else:
        filtered = query.subquery()
        filtered = db.session.query(filtered.c.id, filtered.c.created_at)
    filtered_subquery = filtered.subquery()
    total = db.session.query(func.count()).select_from(filtered_subquery).scalar() or 0
    rows = (
        db.session.query(filtered_subquery.c.id)
        .order_by(filtered_subquery.c.created_at.desc())
        .offset((page - 1) * per_page)
        .limit(per_page)
        .all()
    )
    ids = [row.id for row in rows]
    applications = Application.query.filter(Application.id.in_(ids)).all() if ids else []
    by_id = {item.id: item for item in applications}
    items = [by_id[item_id] for item_id in ids if item_id in by_id]
    return jsonify(
        {
            "applications": [application_to_dict(item, include_private=True) for item in items],
            "pagination": {
                "page": page,
                "per_page": per_page,
                "total": total,
                "pages": (total + per_page - 1) // per_page if per_page else 0,
            },
        }
    )


