# CSV Export endpoint
@api.get("/admin/applications/export")
@require_roles(*ADMIN_ROLES)
def admin_export_applications():
    """Export applications to CSV."""
    import pandas as pd
    from io import BytesIO

    # Get applications with filters
    query = Application.query.join(Job).join(User, Application.candidate_id == User.id)

    # Apply filters from query params
    if request.args.get("status"):
        query = query.filter(Application.internal_status == request.args["status"])
    if request.args.get("job_id"):
        query = query.filter(Application.job_id == request.args["job_id"])
    if request.args.get("source"):
        query = query.filter(Application.source == request.args["source"])

    applications = query.order_by(Application.created_at.desc()).all()

    # Prepare data for CSV
    data = []
    for app in applications:
        candidate = app.candidate
        profile = candidate.profile
        data.append({
            "Application ID": app.public_code or app.id,
            "Application Date": app.created_at.strftime("%Y-%m-%d %H:%M:%S"),
            "Candidate Name": candidate.full_name,
            "Email": candidate.email,
            "Phone": profile.phone if profile else "",
            "Location": profile.current_city if profile else "",
            "Job Title": app.job.title,
            "Job Code": app.job.public_code,
            "Department": app.job.department,
            "Status": app.candidate_status,
            "Internal Status": app.internal_status,
            "Experience (Years)": profile.total_experience_years if profile else "",
            "Current Role": profile.current_role if profile else "",
            "Skills": ", ".join(profile.skills) if profile and profile.skills else "",
            "Source": app.source or "Direct",
            "Resume": "Yes" if app.resume_id else "No",
            "Withdrawn": "Yes" if app.withdrawn_at else "No",
            "Last Updated": app.updated_at.strftime("%Y-%m-%d %H:%M:%S"),
        })

    # Create DataFrame
    df = pd.DataFrame(data)

    # Create CSV in memory
    output = BytesIO()
    df.to_csv(output, index=False, encoding='utf-8')
    output.seek(0)

    # Create response
    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    filename = f"pravaron_applications_{timestamp}.csv"

    return Response(
        output.getvalue(),
        mimetype="text/csv",
        headers={"Content-Disposition": f"attachment; filename={filename}"}
    )


# Interview management endpoints
@api.patch("/admin/interviews/<interview_id>")
@require_roles(*ADMIN_ROLES)
def admin_update_interview(interview_id: str):
    """Update an existing interview."""
    interview = db.session.get(Interview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)

    data = payload()

    # Update fields
    updateable = {
        "interview_type",
        "scheduled_at",
        "duration_minutes",
        "timezone",
        "meeting_mode",
        "meeting_link",
        "physical_location",
        "candidate_instructions",
        "internal_instructions",
        "status",
    }

    for key in updateable:
        if key in data:
            if key == "scheduled_at":
                interview.scheduled_at = parse_datetime(data[key])
            else:
                setattr(interview, key, data[key])

    # Recalculate end time if duration changed
    if interview.scheduled_at and interview.duration_minutes:
        from datetime import timedelta
        interview.ends_at = interview.scheduled_at + timedelta(minutes=interview.duration_minutes)

    create_audit("interview.updated", "interview", interview.id, g.user, {"fields": sorted(data.keys())})
    db.session.commit()

    return jsonify({"interview": interview_to_dict(interview)})


@api.post("/admin/interviews/<interview_id>/cancel")
@require_roles(*ADMIN_ROLES)
def admin_cancel_interview(interview_id: str):
    """Cancel an interview."""
    interview = db.session.get(Interview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)

    data = payload()
    reason = data.get("reason", "")

    interview.status = "Cancelled"
    interview.internal_instructions = (interview.internal_instructions or "") + f"\n\nCancelled: {reason}"

    # Notify candidate
    application = db.session.get(Application, interview.application_id)
    if application:
        create_notification(
            application.candidate_id,
            f"Interview cancelled: {application.job.title}",
            f"Your scheduled interview has been cancelled. {reason}",
            "interview_cancelled",
            application.id,
        )

    create_audit("interview.cancelled", "interview", interview.id, g.user, {"reason": reason})
    db.session.commit()

    return jsonify({"interview": interview_to_dict(interview)})


@api.post("/admin/interviews/<interview_id>/reschedule")
@require_roles(*ADMIN_ROLES)
def admin_reschedule_interview(interview_id: str):
    """Reschedule an interview."""
    interview = db.session.get(Interview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)

    data = payload()
    new_time = parse_datetime(data.get("scheduled_at"))

    if not new_time:
        return json_error("scheduled_at is required")

    old_time = interview.scheduled_at
    interview.scheduled_at = new_time
    interview.status = "Rescheduled"

    # Recalculate end time
    if interview.duration_minutes:
        from datetime import timedelta
        interview.ends_at = new_time + timedelta(minutes=interview.duration_minutes)

    # Notify candidate
    application = db.session.get(Application, interview.application_id)
    if application:
        create_notification(
            application.candidate_id,
            f"Interview rescheduled: {application.job.title}",
            f"Your interview has been rescheduled to {new_time.strftime('%B %d, %Y at %I:%M %p')}.",
            "interview_rescheduled",
            application.id,
        )

    create_audit("interview.rescheduled", "interview", interview.id, g.user, {
        "old_time": old_time.isoformat() if old_time else None,
        "new_time": new_time.isoformat()
    })
    db.session.commit()

    return jsonify({"interview": interview_to_dict(interview)})


# Enhanced analytics endpoint
@api.get("/admin/analytics")
@require_roles(*ADMIN_ROLES)
def admin_analytics():
    """Get comprehensive recruitment analytics."""
    from sqlalchemy import func
    from datetime import datetime, timedelta

    # Date range filter (default last 90 days)
    days = int(request.args.get("days", 90))
    start_date = datetime.now(timezone.utc) - timedelta(days=days)

    # Applications by job
    apps_by_job = db.session.query(
        Job.title,
        Job.public_code,
        func.count(Application.id).label("count")
    ).join(Application).filter(
        Application.created_at >= start_date
    ).group_by(Job.id, Job.title, Job.public_code).all()

    # Applications by status
    apps_by_status = db.session.query(
        Application.candidate_status,
        func.count(Application.id).label("count")
    ).filter(
        Application.created_at >= start_date
    ).group_by(Application.candidate_status).all()

    # Applications by source
    apps_by_source = db.session.query(
        Application.source,
        func.count(Application.id).label("count")
    ).filter(
        Application.created_at >= start_date
    ).group_by(Application.source).all()

    # Applications by date (daily)
    apps_by_date = db.session.query(
        func.date(Application.created_at).label("date"),
        func.count(Application.id).label("count")
    ).filter(
        Application.created_at >= start_date
    ).group_by(func.date(Application.created_at)).order_by(func.date(Application.created_at)).all()

    # Stage conversion rates
    total_apps = Application.query.filter(Application.created_at >= start_date).count()
    shortlisted = Application.query.filter(
        Application.created_at >= start_date,
        Application.internal_status == "Shortlisted"
    ).count()
    interviewed = Application.query.filter(
        Application.created_at >= start_date,
        Application.internal_status.in_(["Interview Scheduled", "Interview Completed"])
    ).count()
    offered = Application.query.filter(
        Application.created_at >= start_date,
        Application.internal_status == "Offer Sent"
    ).count()
    hired = Application.query.filter(
        Application.created_at >= start_date,
        Application.internal_status == "Hired"
    ).count()
    rejected = Application.query.filter(
        Application.created_at >= start_date,
        Application.internal_status == "Rejected"
    ).count()

    return jsonify({
        "applications_by_job": [{"job": item[0], "code": item[1], "count": item[2]} for item in apps_by_job],
        "applications_by_status": [{"status": item[0], "count": item[1]} for item in apps_by_status],
        "applications_by_source": [{"source": item[0] or "Direct", "count": item[1]} for item in apps_by_source],
        "applications_by_date": [{"date": str(item[0]), "count": item[1]} for item in apps_by_date],
        "conversion": {
            "total": total_apps,
            "shortlisted": shortlisted,
            "shortlist_rate": round(shortlisted / total_apps * 100, 1) if total_apps > 0 else 0,
            "interviewed": interviewed,
            "interview_rate": round(interviewed / total_apps * 100, 1) if total_apps > 0 else 0,
            "offered": offered,
            "offer_rate": round(offered / total_apps * 100, 1) if total_apps > 0 else 0,
            "hired": hired,
            "hire_rate": round(hired / total_apps * 100, 1) if total_apps > 0 else 0,
            "rejected": rejected,
            "rejection_rate": round(rejected / total_apps * 100, 1) if total_apps > 0 else 0,
        },
        "date_range": {
            "start": start_date.strftime("%Y-%m-%d"),
            "end": datetime.now(timezone.utc).strftime("%Y-%m-%d"),
            "days": days,
        }
    })



