@api.get("/admin/reviewer/applications")
@require_roles(*REVIEWER_ROLES)
def reviewer_assigned_applications():
    """Reviewer portal: list applications assigned to the current reviewer."""
    assignments = ReviewerAssignment.query.filter_by(reviewer_id=g.user.id).all()
    app_ids = list({a.application_id for a in assignments if a.application_id})
    job_ids = list({a.job_id for a in assignments if a.job_id})

    query = Application.query
    if app_ids and job_ids:
        query = query.filter(or_(Application.id.in_(app_ids), Application.job_id.in_(job_ids)))
    elif app_ids:
        query = query.filter(Application.id.in_(app_ids))
    elif job_ids:
        query = query.filter(Application.job_id.in_(job_ids))
    else:
        return jsonify({"applications": [], "total": 0})

    page = int(request.args.get("page", 1))
    per_page = min(int(request.args.get("per_page", 20)), 100)
    paginated = query.order_by(Application.created_at.desc()).paginate(page=page, per_page=per_page, error_out=False)
    return jsonify({
        "applications": [application_to_dict(a, include_private=True) for a in paginated.items],
        "total": paginated.total,
        "page": page,
        "pages": paginated.pages,
    })


@api.patch("/candidate/profile/notification-preferences")
@require_roles("candidate")
def update_notification_preferences():
    """Save candidate notification preference flags."""
    data = payload()
    profile = g.user.profile
    if not profile:
        return json_error("Profile not found", 404)
    prefs = profile.extra_metadata or {}
    allowed_keys = {"email_on_status_change", "email_on_interview", "email_on_offer", "email_digest"}
    for key in allowed_keys:
        if key in data:
            prefs[key] = bool(data[key])
    profile.extra_metadata = prefs
    db.session.commit()
    return jsonify({"notification_preferences": {k: prefs.get(k) for k in allowed_keys}})


@api.post("/admin/interviews/<interview_id>/feedback")
@require_roles(*REVIEWER_ROLES)
def submit_interview_feedback(interview_id: str):
    """Interviewer submits structured feedback."""
    interview = db.session.get(Interview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    data = payload()
    feedback = InterviewFeedback.query.filter_by(interview_id=interview_id, reviewer_id=g.user.id).first()
    if not feedback:
        feedback = InterviewFeedback(interview_id=interview_id, reviewer_id=g.user.id)
        db.session.add(feedback)

    for field in ("technical_score", "communication_score", "problem_solving_score", "cultural_fit_score"):
        val = data.get(field)
        if val is not None:
            try:
                setattr(feedback, field, max(1, min(10, int(val))))
            except (TypeError, ValueError):
                pass
    if "overall_recommendation" in data:
        rec = str(data["overall_recommendation"]).strip()
        if rec in ("Hire", "Consider", "Reject"):
            feedback.overall_recommendation = rec
    for field in ("strengths", "concerns", "notes"):
        if field in data:
            setattr(feedback, field, str(data[field])[:2000])

    db.session.commit()
    create_audit("interview.feedback_submitted", "interview", interview_id, g.user)
    return jsonify({"feedback": interview_feedback_to_dict(feedback)})


@api.get("/admin/interviews/<interview_id>/feedback")
@require_roles(*REVIEWER_ROLES)
def get_interview_feedback(interview_id: str):
    """Get interview feedback entries."""
    feedbacks = InterviewFeedback.query.filter_by(interview_id=interview_id).all()
    return jsonify({"feedback": [interview_feedback_to_dict(f) for f in feedbacks]})


@api.post("/admin/applications/<application_id>/offer")
@api.patch("/admin/applications/<application_id>/offer")
@require_roles(*ADMIN_ROLES)
def create_offer_letter(application_id: str):
    """Create or update offer letter for application."""
    application = db.session.get(Application, application_id)
    if not application:
        return json_error("Application not found", 404)
    data = payload()
    offer = OfferLetter.query.filter_by(application_id=application_id).first()
    if not offer:
        offer = OfferLetter(application_id=application_id, created_by_id=g.user.id)
        db.session.add(offer)

    if "role_title" in data:
        offer.role_title = str(data["role_title"])[:180]
    if "department" in data:
        offer.department = str(data.get("department", ""))[:120]
    if "joining_date" in data and data["joining_date"]:
        try:
            from datetime import date
            offer.joining_date = date.fromisoformat(str(data["joining_date"]))
        except ValueError:
            pass
    if "compensation_details" in data:
        offer.compensation_details = str(data["compensation_details"])[:5000]
    if "additional_terms" in data:
        offer.additional_terms = str(data["additional_terms"])[:5000]
    if "status" in data and data["status"] in ("draft", "sent", "accepted", "declined"):
        old_status = offer.status
        offer.status = data["status"]
        if data["status"] == "sent" and old_status != "sent":
            offer.sent_at = utcnow()
        elif data["status"] in ("accepted", "declined") and not offer.responded_at:
            offer.responded_at = utcnow()

    db.session.commit()
    create_audit("offer_letter.updated", "application", application_id, g.user)
    serialized = offer_letter_to_dict(offer)
    return jsonify({"offer": serialized, "offer_letter": serialized})


@api.get("/admin/applications/<application_id>/offer")
@require_roles(*ADMIN_ROLES)
def get_offer_letter(application_id: str):
    offer = OfferLetter.query.filter_by(application_id=application_id).first()
    serialized = offer_letter_to_dict(offer)
    return jsonify({"offer": serialized, "offer_letter": serialized})


