@api.post("/admin/applications/<application_id>/offer/send")
@require_roles(*ADMIN_ROLES)
def send_offer_letter(application_id: str):
    application = db.session.get(Application, application_id)
    if not application:
        return json_error("Application not found", 404)
    offer = OfferLetter.query.filter_by(application_id=application_id).first()
    if not offer:
        return json_error("Create an offer letter before sending it", 404)
    if not offer.role_title:
        return json_error("role_title is required before sending the offer")
    if offer.status in ("accepted", "declined"):
        return json_error("This offer has already received a candidate response", 409)
    offer.status = "sent"
    if not offer.sent_at:
        offer.sent_at = utcnow()
    update_application_status(application, "Offer Sent", g.user, "Offer released to candidate.")
    create_audit("offer_letter.sent", "application", application_id, g.user)
    db.session.commit()
    serialized = offer_letter_to_dict(offer)
    return jsonify({"offer": serialized, "offer_letter": serialized, "application": application_to_dict(application, include_private=True)})

@api.get("/admin/candidates/search")
@require_roles(*ADMIN_ROLES)
def candidate_search():
    """Full-text keyword search across candidate name/email/skills/resume content."""
    from sqlalchemy import func
    from .models import ApplicantDetail, CandidateAnalysis

    q = request.args.get("q", "").strip()
    skills_filter = [s.strip().lower() for s in request.args.get("skills", "").split(",") if s.strip()]
    score_min = request.args.get("score_min")
    track = request.args.get("track", "").strip()
    page = int(request.args.get("page", 1))
    per_page = min(int(request.args.get("per_page", 20)), 100)

    query = Application.query.join(Application.candidate).outerjoin(Application.applicant_detail).outerjoin(Application.candidate_analysis)

    if q:
        pattern = f"%{q.lower()}%"
        query = query.filter(
            or_(
                func.lower(User.full_name).like(pattern),
                func.lower(User.email).like(pattern),
                func.lower(ApplicantDetail.resume_text).like(pattern),
                func.lower(ApplicantDetail.current_role).like(pattern),
            )
        )

    if skills_filter:
        from .models import CandidateAnalysis as CA
        for skill in skills_filter[:5]:
            query = query.filter(
                or_(
                    func.lower(func.cast(CA.skills, db.Text)).like(f"%{skill}%"),
                    func.lower(func.cast(CA.frameworks, db.Text)).like(f"%{skill}%"),
                )
            )

    if score_min:
        try:
            query = query.filter(CandidateAnalysis.suitability_score >= int(score_min))
        except ValueError:
            pass

    if track in ("Internship", "Full-time"):
        query = query.filter(CandidateAnalysis.recommended_track == track)

    paginated = query.order_by(Application.created_at.desc()).paginate(page=page, per_page=per_page, error_out=False)
    return jsonify({
        "results": [application_to_dict(a, include_private=True) for a in paginated.items],
        "total": paginated.total,
        "page": page,
        "pages": paginated.pages,
        "query": q,
    })


@api.get("/admin/candidates/duplicates")
@require_roles(*ADMIN_ROLES)
def detect_duplicate_candidates():
    """Detect candidates who have applied multiple times or share similar names."""
    from sqlalchemy import func
    from .models import ApplicantDetail

    # Find users with multiple applications
    multi_apps = (
        db.session.query(Application.candidate_id, func.count(Application.id).label("app_count"))
        .group_by(Application.candidate_id)
        .having(func.count(Application.id) > 1)
        .all()
    )

    duplicates = []
    for candidate_id, count in multi_apps[:50]:
        user = db.session.get(User, candidate_id)
        if user:
            apps = Application.query.filter_by(candidate_id=candidate_id).order_by(Application.created_at.desc()).all()
            duplicates.append({
                "candidate_id": candidate_id,
                "candidate_name": user.full_name,
                "candidate_email": user.email,
                "application_count": count,
                "applications": [
                    {"id": a.id, "job_title": a.job.title if a.job else None, "status": a.candidate_status, "created_at": a.created_at.isoformat()}
                    for a in apps
                ],
            })

    return jsonify({"duplicates": duplicates, "total": len(duplicates)})


@api.post("/admin/applications/<application_id>/inconsistencies")
@require_roles(*ADMIN_ROLES)
def run_inconsistency_check(application_id: str):
    """Run AI inconsistency detection on an application."""
    application = db.session.get(Application, application_id)
    if not application:
        return json_error("Application not found", 404)
    try:
        flag_record = detect_inconsistencies(application)
        return jsonify({"inconsistencies": inconsistency_flag_to_dict(flag_record)})
    except Exception as exc:
        return json_error(str(exc), 500)


@api.get("/admin/applications/<application_id>/inconsistencies")
@require_roles(*ADMIN_ROLES)
def get_inconsistencies(application_id: str):
    flag = InconsistencyFlag.query.filter_by(application_id=application_id).first()
    return jsonify({"inconsistencies": inconsistency_flag_to_dict(flag)})


@api.patch("/admin/applications/<application_id>/inconsistencies")
@require_roles(*ADMIN_ROLES)
def review_inconsistencies(application_id: str):
    flag = InconsistencyFlag.query.filter_by(application_id=application_id).first()
    if not flag:
        return json_error("No inconsistency record found", 404)
    data = payload()
    flag.reviewed = True
    flag.reviewer_note = str(data.get("reviewer_note", ""))[:1000]
    db.session.commit()
    return jsonify({"inconsistencies": inconsistency_flag_to_dict(flag)})


