@api.get("/candidate/assessments")
@require_roles("candidate")
def candidate_list_assessments():
    """List all assessments assigned to the current candidate."""
    attempts = AssessmentAttempt.query.filter_by(candidate_id=g.user.id).order_by(AssessmentAttempt.created_at.desc()).all()
    result = []
    for attempt in attempts:
        a_dict = attempt_to_dict(attempt)
        a_dict["assessment"] = assessment_to_dict(attempt.assessment)
        result.append(a_dict)
    return jsonify({"assessments": result})


@api.post("/candidate/assessments/<assessment_id>/start")
@require_roles("candidate")
def start_assessment(assessment_id: str):
    """Start an assessment attempt."""
    from datetime import timedelta
    attempt = AssessmentAttempt.query.filter_by(
        assessment_id=assessment_id, candidate_id=g.user.id
    ).first()
    if not attempt:
        return json_error("Assessment not assigned to you", 404)
    if attempt.status == "in_progress":
        return jsonify({"attempt": attempt_to_dict(attempt), "assessment": assessment_to_dict(attempt.assessment, include_questions=True)})
    if attempt.status in ("submitted", "timed_out", "graded"):
        return json_error("Assessment already completed", 400)

    existing_count = AssessmentAttempt.query.filter_by(
        assessment_id=assessment_id, candidate_id=g.user.id
    ).filter(AssessmentAttempt.status.in_(["submitted", "timed_out", "graded"])).count()
    if existing_count >= attempt.assessment.max_attempts:
        return json_error("Maximum attempts reached", 400)

    attempt.status = "in_progress"
    attempt.started_at = utcnow()
    attempt.expires_at = utcnow() + timedelta(minutes=attempt.assessment.time_limit_minutes)
    db.session.commit()

    questions = attempt.assessment.questions
    if attempt.assessment.randomize_questions:
        import random
        questions = list(questions)
        random.shuffle(questions)

    return jsonify({
        "attempt": attempt_to_dict(attempt),
        "assessment": assessment_to_dict(attempt.assessment),
        "questions": [assessment_question_to_dict(q, include_answer=False) for q in questions],
    })


@api.get("/candidate/assessments/attempts/<attempt_id>")
@require_roles("candidate")
def get_candidate_attempt(attempt_id: str):
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt or attempt.candidate_id != g.user.id:
        return json_error("Attempt not found", 404)
    return jsonify({
        "attempt": attempt_to_dict(attempt, include_responses=True),
        "questions": [assessment_question_to_dict(q, include_answer=False) for q in attempt.assessment.questions],
    })


@api.post("/candidate/assessments/attempts/<attempt_id>/responses")
@require_roles("candidate")
def save_assessment_response(attempt_id: str):
    """Save or update a single response."""
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt or attempt.candidate_id != g.user.id:
        return json_error("Attempt not found", 404)
    if attempt.status != "in_progress":
        return json_error("Attempt is not in progress", 400)
    if attempt.expires_at and ensure_utc(attempt.expires_at) < ensure_utc(utcnow()):
        attempt.status = "timed_out"
        db.session.commit()
        return json_error("Assessment time expired", 400)

    data = payload()
    question_id = data.get("question_id")
    if not question_id:
        return json_error("question_id is required")

    question = db.session.get(AssessmentQuestion, question_id)
    if not question or question.assessment_id != attempt.assessment_id:
        return json_error("Question not found", 404)

    response = AssessmentResponse.query.filter_by(attempt_id=attempt_id, question_id=question_id).first()
    if not response:
        response = AssessmentResponse(attempt_id=attempt_id, question_id=question_id)
        db.session.add(response)
    response.response = data.get("response")
    if "time_taken_seconds" in data:
        try:
            response.time_taken_seconds = int(data["time_taken_seconds"])
        except (TypeError, ValueError):
            pass
    db.session.commit()
    return jsonify({"response": assessment_response_to_dict(response)})


@api.post("/candidate/assessments/attempts/<attempt_id>/submit")
@require_roles("candidate")
def submit_assessment(attempt_id: str):
    """Final submission of the assessment."""
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt or attempt.candidate_id != g.user.id:
        return json_error("Attempt not found", 404)
    if attempt.status not in ("in_progress", "not_started"):
        return json_error("Cannot submit: assessment is already " + attempt.status, 400)

    attempt.status = "submitted"
    attempt.submitted_at = utcnow()
    db.session.commit()

    try:
        auto_grade_attempt(attempt)
    except Exception:
        db.session.rollback()

    create_audit("assessment.submitted", "assessment_attempt", attempt_id, g.user)
    return jsonify({"attempt": attempt_to_dict(attempt)})


@api.post("/candidate/assessments/attempts/<attempt_id>/proctoring/start")
@require_roles("candidate")
def start_proctoring_session(attempt_id: str):
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt or attempt.candidate_id != g.user.id:
        return json_error("Attempt not found", 404)
    if attempt.proctoring_session:
        return jsonify({"session": proctoring_session_to_dict(attempt.proctoring_session)})

    data = payload()
    session = ProctoringSession(
        attempt_id=attempt_id,
        device_info=data.get("device_info") or {},
        ip_address=request.remote_addr,
        started_at=utcnow(),
    )
    db.session.add(session)
    db.session.commit()
    return jsonify({"session": proctoring_session_to_dict(session)}), 201


@api.post("/candidate/assessments/attempts/<attempt_id>/proctoring/event")
@require_roles("candidate")
def log_proctoring_event(attempt_id: str):
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt or attempt.candidate_id != g.user.id:
        return json_error("Attempt not found", 404)
    session = attempt.proctoring_session
    if not session:
        return json_error("Proctoring session not started", 400)

    data = payload()
    event_type = str(data.get("event_type", ""))[:60]
    severity = str(data.get("severity", "low"))[:20]
    if severity not in ("low", "medium", "high"):
        severity = "low"

    event = ProctoringEvent(
        session_id=session.id,
        event_type=event_type,
        severity=severity,
        description=str(data.get("description", ""))[:500],
        metadata=data.get("metadata") or {},
        occurred_at=utcnow(),
    )
    db.session.add(event)

    # Update counters
    weight_map = {"low": 1, "medium": 2, "high": 4}
    if event_type == "fullscreen_exit":
        session.fullscreen_exits += 1
    elif event_type == "tab_switch":
        session.tab_switches += 1
    elif event_type == "focus_loss":
        session.focus_losses += 1
    elif event_type in ("copy_paste", "copy", "paste", "cut"):
        session.copy_paste_events += 1
    elif event_type == "face_not_detected":
        session.face_not_detected_count += 1
    elif event_type == "multiple_faces":
        session.multiple_faces_count += 1
    elif event_type == "mobile_detected":
        session.mobile_detected_count += 1
    session.suspicious_total += weight_map.get(severity, 1)

    db.session.commit()
    return jsonify({"logged": True, "event_type": event_type})


@api.get("/admin/assessments/attempts/<attempt_id>/proctoring")
@require_roles(*ADMIN_ROLES)
def get_proctoring_report(attempt_id: str):
    attempt = db.session.get(AssessmentAttempt, attempt_id)
    if not attempt:
        return json_error("Attempt not found", 404)
    return jsonify({
        "proctoring": proctoring_session_to_dict(attempt.proctoring_session, include_events=True) if attempt.proctoring_session else None
    })


