@api.get("/admin/interviews/setup")
@require_roles(*ADMIN_ROLES)
def get_interview_setup():
    mode = request.args.get("mode") or "mcq"
    job_id = request.args.get("job_id")
    query = AIInterviewQuestionTemplate.query.filter_by(mode=mode)
    if job_id:
        query = query.filter(AIInterviewQuestionTemplate.job_id == job_id)
    templates = query.order_by(AIInterviewQuestionTemplate.job_id.asc(), AIInterviewQuestionTemplate.category.asc(), AIInterviewQuestionTemplate.order.asc(), AIInterviewQuestionTemplate.created_at.asc()).all()
    jobs = Job.query.order_by(Job.title.asc()).all()
    return jsonify({
        "jobs": [job_to_dict(job, include_private=True) for job in jobs],
        "questions": [ai_interview_question_template_to_dict(template) for template in templates],
    })


@api.post("/admin/interviews/setup/questions")
@require_roles(*ADMIN_ROLES)
def create_interview_setup_question():
    data = payload()
    job_id = data.get("job_id")
    job = db.session.get(Job, job_id) if job_id else None
    if not job:
        return json_error("Valid job_id is required")
    mode = str(data.get("mode") or "mcq").strip().lower()
    if mode not in {"mcq", "code"}:
        return json_error("mode must be mcq or code")
    category = str(data.get("category") or "technical").strip().lower()
    if category not in {"aptitude", "gk", "technical"}:
        return json_error("category must be aptitude, gk, or technical")
    content = str(data.get("content") or "").strip()
    if len(content) < 10:
        return json_error("Question text is required")
    options = [str(option).strip() for option in (data.get("options") or []) if str(option).strip()]
    correct_answer = str(data.get("correct_answer") or "").strip()
    if mode == "mcq":
        if len(options) < 2:
            return json_error("At least two MCQ options are required")
        if correct_answer not in options:
            return json_error("Correct answer must match one of the options")
    template = AIInterviewQuestionTemplate(
        job_id=job.id,
        mode=mode,
        category=category,
        content=content,
        options=options[:6] if mode == "mcq" else [],
        correct_answer=correct_answer if mode == "mcq" else None,
        marks=max(1, int(data.get("marks") or 1)),
        difficulty=str(data.get("difficulty") or "standard")[:40],
        order=max(0, int(data.get("order") or 0)),
        created_by_id=g.user.id,
    )
    db.session.add(template)
    db.session.commit()
    create_audit("ai_interview_question.created", "job", job.id, g.user)
    return jsonify({"question": ai_interview_question_template_to_dict(template)}), 201


@api.delete("/admin/interviews/setup/questions/<question_id>")
@require_roles(*ADMIN_ROLES)
def delete_interview_setup_question(question_id: str):
    template = db.session.get(AIInterviewQuestionTemplate, question_id)
    if not template:
        return json_error("Question not found", 404)
    job_id = template.job_id
    db.session.delete(template)
    db.session.commit()
    create_audit("ai_interview_question.deleted", "job", job_id, g.user)
    return jsonify({"ok": True})

@api.get("/admin/interviews/ai")
@require_roles(*ADMIN_ROLES)
def list_ai_interviews():
    status_filter = request.args.get("status")
    query = AIInterview.query
    if status_filter:
        query = query.filter(AIInterview.status == status_filter)
    interviews = query.order_by(AIInterview.created_at.desc()).all()
    return jsonify({"interviews": [ai_interview_to_dict(i) for i in interviews]})


@api.post("/admin/interviews/ai")
@require_roles(*ADMIN_ROLES)
def schedule_ai_interview():
    data = payload()
    application_id = data.get("application_id")
    if not application_id:
        return json_error("application_id is required")
    application = db.session.get(Application, application_id)
    if not application:
        return json_error("Application not found", 404)
    existing = AIInterview.query.filter_by(application_id=application_id).first()
    if existing:
        return json_error("Interview already scheduled for this application", 400)

    interview = AIInterview(
        application_id=application_id,
        candidate_id=application.candidate_id,
        status="scheduled",
        invitation_sent_at=utcnow(),
        mcq_config={"access_code": _generate_interview_access_code()},
    )
    db.session.add(interview)
    db.session.commit()

    send_ai_interview_invitation(application, interview)
    create_audit("ai_interview.scheduled", "application", application_id, g.user)
    return jsonify({"interview": ai_interview_to_dict(interview)}), 201


@api.get("/admin/interviews/ai/<interview_id>")
@require_roles(*ADMIN_ROLES)
def get_ai_interview_admin(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    return jsonify({"interview": ai_interview_to_dict(interview, include_transcript=True)})


@api.delete("/admin/interviews/ai/<interview_id>")
@require_roles(*ADMIN_ROLES)
def delete_ai_interview(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    application_id = interview.application_id
    db.session.delete(interview)
    db.session.commit()
    create_audit("ai_interview.deleted", "application", application_id, g.user)
    return jsonify({"ok": True})


@api.get("/admin/interviews/ai/<interview_id>/live")
@require_roles(*ADMIN_ROLES)
def get_ai_interview_live(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    return jsonify({
        "status": interview.status,
        "latest_frame_data_url": interview.latest_frame_data_url,
        "latest_frame_at": interview.latest_frame_at.isoformat() if interview.latest_frame_at else None,
        "proctoring_summary": interview.proctoring_summary or {},
        "security_events": (interview.security_events or [])[-80:],
        "admin_messages": interview.admin_messages or [],
        "started_at": interview.started_at.isoformat() if interview.started_at else None,
    })


@api.post("/admin/interviews/ai/<interview_id>/messages")
@require_roles(*ADMIN_ROLES)
def send_ai_interview_admin_message(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    body = str(payload().get("message") or "").strip()
    if not body:
        return json_error("message is required")
    message = {
        "id": str(uuid.uuid4()),
        "sender_id": g.user.id,
        "sender_name": g.user.full_name,
        "message": body[:500],
        "created_at": utcnow().isoformat(),
    }
    messages = list(interview.admin_messages or [])
    messages.append(message)
    interview.admin_messages = messages[-100:]
    create_audit("ai_interview.admin_message_sent", "ai_interview", interview_id, g.user)
    db.session.commit()
    return jsonify({"message": message, "messages": interview.admin_messages})

@api.patch("/admin/interviews/ai/<interview_id>/review")
@require_roles(*ADMIN_ROLES)
def review_ai_interview(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    data = payload()
    if "recommendation" in data and data["recommendation"] in ("Proceed", "Hold", "Reject"):
        interview.recommendation = data["recommendation"]
    if "reviewer_notes" in data:
        interview.reviewer_notes = str(data["reviewer_notes"])[:5000]
    interview.reviewed_by_id = g.user.id
    interview.reviewed_at = utcnow()
    interview.status = "reviewed"
    db.session.commit()
    create_audit("ai_interview.reviewed", "ai_interview", interview_id, g.user)
    return jsonify({"interview": ai_interview_to_dict(interview, include_transcript=True)})


