def _default_interview_proctoring() -> dict:
    return {
        "tab_switches": 0,
        "focus_losses": 0,
        "fullscreen_exits": 0,
        "copy_paste_events": 0,
        "face_not_detected": 0,
        "multiple_faces": 0,
        "mobile_detected": 0,
        "camera_disabled": 0,
        "look_away": 0,
        "suspicious_total": 0,
    }

def _generate_interview_access_code() -> str:
    return uuid.uuid4().hex[:6].upper()


def _ensure_interview_access_code(interview: AIInterview) -> str:
    config = dict(interview.mcq_config or {})
    code = str(config.get("access_code") or "").strip().upper()
    if len(code) < 4:
        code = _generate_interview_access_code()
        config["access_code"] = code
        interview.mcq_config = config
    return code


def _public_interview_config(config: dict | None) -> dict:
    public_config = dict(config or {})
    public_config.pop("access_code", None)
    return public_config


def _request_interview_access_code() -> str:
    code = request.args.get("access_code") or request.args.get("code")
    if not code and request.is_json:
        body = payload()
        code = body.get("access_code") or body.get("code")
    if not code and request.form:
        code = request.form.get("access_code") or request.form.get("code")
    return str(code or "").strip().upper().replace(" ", "")


def _interview_code_matches(interview: AIInterview, code: str) -> bool:
    expected = str((interview.mcq_config or {}).get("access_code") or "").strip().upper()
    return bool(expected and code and expected == code)


def _record_interview_security_event(interview: AIInterview, event_type: str, severity: str, description: str, metadata: dict | None = None) -> dict:
    severity = severity if severity in {"low", "medium", "high"} else "medium"
    event = {
        "id": str(uuid.uuid4()),
        "event_type": str(event_type or "unknown")[:80],
        "severity": severity,
        "description": str(description or "Security event")[:500],
        "metadata": metadata if isinstance(metadata, dict) else {},
        "occurred_at": utcnow().isoformat(),
    }
    events = list(interview.security_events or [])
    events.append(event)
    interview.security_events = events[-300:]
    summary = dict(interview.proctoring_summary or _default_interview_proctoring())
    counter_map = {
        "tab_switch": "tab_switches",
        "focus_loss": "focus_losses",
        "fullscreen_exit": "fullscreen_exits",
        "copy_paste": "copy_paste_events",
        "face_not_detected": "face_not_detected",
        "multiple_faces": "multiple_faces",
        "mobile_detected": "mobile_detected",
        "camera_disabled": "camera_disabled",
        "look_away": "look_away",
    }
    key = counter_map.get(event["event_type"])
    if key:
        summary[key] = int(summary.get(key) or 0) + 1
    weight = {"low": 1, "medium": 2, "high": 4}[severity]
    summary["suspicious_total"] = int(summary.get("suspicious_total") or 0) + weight
    interview.proctoring_summary = summary
    return event

def _get_candidate_interview(interview_id: str) -> AIInterview | None:
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return None
    user = current_user()
    if user:
        g.user = user
        if user.role == "candidate" and interview.candidate_id != user.id:
            return None
        return interview
    if _interview_code_matches(interview, _request_interview_access_code()):
        g.user = interview.candidate
        return interview
    return None


@api.get("/public/interviews/ai/<interview_id>")
def public_ai_interview_summary(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    application = interview.application
    job = application.job if application else None
    candidate = interview.candidate
    return jsonify({
        "interview": {
            "id": interview.id,
            "candidate_name": candidate.full_name if candidate else None,
            "job_title": job.title if job else None,
            "status": interview.status,
            "requires_code": True,
        }
    })


@api.post("/public/interviews/ai/<interview_id>/verify")
def verify_public_ai_interview_code(interview_id: str):
    interview = db.session.get(AIInterview, interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    _ensure_interview_access_code(interview)
    if not _interview_code_matches(interview, _request_interview_access_code()):
        return json_error("Invalid interview code", 403)
    db.session.commit()
    data = ai_interview_to_dict(interview, include_transcript=interview.status in ("in_progress", "completed", "reviewed"))
    data["mcq_config"] = _public_interview_config(data.get("mcq_config"))
    return jsonify({"interview": data})

@api.get("/candidate/interviews/ai")
def candidate_list_ai_interviews():
    user = current_user()
    if not user:
        return jsonify({"interviews": []})
    g.user = user
    interviews = AIInterview.query.filter_by(candidate_id=g.user.id).order_by(AIInterview.created_at.desc()).all()
    return jsonify({"interviews": [ai_interview_to_dict(i) for i in interviews]})


@api.get("/candidate/interviews/ai/<interview_id>")
def candidate_get_ai_interview(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    return jsonify({"interview": ai_interview_to_dict(interview, include_transcript=interview.status in ("in_progress", "completed", "reviewed"))})


@api.post("/candidate/interviews/ai/<interview_id>/start")
def start_ai_interview(interview_id: str):
    """Candidate starts the secured 30-question MCQ interview."""
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status in ("completed", "reviewed"):
        return json_error("Interview already completed", 400)
    if interview.status == "in_progress" and interview.questions:
        answered_ids = {r.question_id for r in interview.responses}
        unanswered = [q for q in interview.questions if q.id not in answered_ids]
        next_q = unanswered[0] if unanswered else None
        return jsonify({
            "interview": ai_interview_to_dict(interview),
            "next_question": ai_interview_question_to_dict(next_q) if next_q else None,
            "total_questions": len(interview.questions),
            "time_limit_seconds": (interview.mcq_config or {}).get("time_limit_minutes", 60) * 60,
            "status": "in_progress",
        })

    interview.status = "in_progress"
    interview.started_at = interview.started_at or utcnow()
    interview.mcq_config = interview.mcq_config or {}
    interview.proctoring_summary = interview.proctoring_summary or _default_interview_proctoring()
    questions = generate_opening_questions(interview)
    first_question = questions[0] if questions else None
    if first_question:
        first_question.asked_at = utcnow()
    db.session.commit()

    create_audit("ai_interview.started", "ai_interview", interview_id, g.user)
    return jsonify({
        "interview": ai_interview_to_dict(interview),
        "next_question": ai_interview_question_to_dict(first_question) if first_question else None,
        "total_questions": len(questions),
        "time_limit_seconds": (interview.mcq_config or {}).get("time_limit_minutes", 60) * 60,
    })


@api.get("/candidate/interviews/ai/<interview_id>/next-question")
def get_next_ai_question(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status != "in_progress":
        return json_error("Interview is not in progress", 400)

    answered_ids = {r.question_id for r in interview.responses}
    unanswered = [q for q in interview.questions if q.id not in answered_ids]

    if not unanswered:
        return jsonify({"next_question": None, "interview_complete": True})

    next_q = unanswered[0]
    if not next_q.asked_at:
        next_q.asked_at = utcnow()
        db.session.commit()

    return jsonify({
        "next_question": ai_interview_question_to_dict(next_q),
        "questions_remaining": len(unanswered),
        "interview_complete": False,
    })


@api.post("/candidate/interviews/ai/<interview_id>/respond")
def submit_ai_interview_response(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status != "in_progress":
        return json_error("Interview is not in progress", 400)

    if interview.started_at and duration_seconds(interview.started_at, utcnow()) > int((interview.mcq_config or {}).get("time_limit_minutes", 60)) * 60:
        interview.status = "completed"
        interview.completed_at = utcnow()
        interview.total_duration_seconds = duration_seconds(interview.started_at, interview.completed_at)
        generate_interview_summary(interview)
        db.session.commit()
        return json_error("Interview time limit has expired", 409)

    data = payload()
    question_id = data.get("question_id")
    if not question_id:
        return json_error("question_id is required")

    question = db.session.get(AIInterviewQuestion, question_id)
    if not question or question.interview_id != interview_id:
        return json_error("Question not found", 404)

    existing = AIInterviewResponse.query.filter_by(question_id=question_id).first()
    if existing:
        answered_ids = {r.question_id for r in interview.responses}
        unanswered = [q for q in interview.questions if q.id not in answered_ids]
        next_q = unanswered[0] if unanswered else None
        if next_q and not next_q.asked_at:
            next_q.asked_at = utcnow()
            db.session.commit()
        return jsonify({
            "response_saved": True,
            "next_question": ai_interview_question_to_dict(next_q) if next_q else None,
            "questions_remaining": len(unanswered),
            "completed": next_q is None,
            "interview_complete": next_q is None,
            "total_questions": len(interview.questions),
        })

    response_text = str(data.get("response_text", ""))[:10000]
    if response_text not in (question.options or []):
        return json_error("Selected answer is not valid for this question")
    duration = max(0, int(data.get("duration_seconds", 0) or 0))
    is_correct = response_text == question.correct_answer

    resp = AIInterviewResponse(
        interview_id=interview_id,
        question_id=question_id,
        response_text=response_text,
        is_correct=is_correct,
        response_duration_seconds=duration,
        submitted_at=utcnow(),
        ai_quality_notes={"category": question.category, "is_correct": is_correct},
    )
    db.session.add(resp)
    db.session.flush()

    answered_ids = {r.question_id for r in interview.responses}
    unanswered = [q for q in interview.questions if q.id not in answered_ids]
    next_question = None
    if unanswered:
        next_q = unanswered[0]
        next_q.asked_at = next_q.asked_at or utcnow()
        next_question = ai_interview_question_to_dict(next_q)
    db.session.commit()

    return jsonify({
        "response_saved": True,
        "next_question": next_question,
        "questions_remaining": len(unanswered),
        "completed": next_question is None,
        "interview_complete": next_question is None,
        "total_questions": len(interview.questions),
    })


@api.post("/candidate/interviews/ai/<interview_id>/proctoring/event")
def log_ai_interview_security_event(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status not in ("in_progress", "completed"):
        return json_error("Interview is not active", 400)
    data = payload()
    event = _record_interview_security_event(
        interview,
        str(data.get("event_type") or "unknown"),
        str(data.get("severity") or "medium"),
        str(data.get("description") or "Security event"),
        data.get("metadata") if isinstance(data.get("metadata"), dict) else {},
    )
    db.session.commit()
    return jsonify({"event": event, "proctoring_summary": interview.proctoring_summary})


@api.post("/candidate/interviews/ai/<interview_id>/live-frame")
def update_ai_interview_live_frame(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status != "in_progress":
        return json_error("Interview is not live", 400)
    data_url = str(payload().get("frame_data_url") or "")
    if not data_url.startswith("data:image/jpeg;base64,"):
        return json_error("frame_data_url must be a JPEG data URL")
    if len(data_url) > 450000:
        return json_error("frame is too large")
    interview.latest_frame_data_url = data_url
    interview.latest_frame_at = utcnow()
    summary = dict(interview.proctoring_summary or _default_interview_proctoring())
    summary["live_frame_count"] = int(summary.get("live_frame_count") or 0) + 1
    interview.proctoring_summary = summary
    db.session.commit()
    return jsonify({"ok": True, "latest_frame_at": interview.latest_frame_at.isoformat()})


@api.post("/candidate/interviews/ai/<interview_id>/recording")
def upload_ai_interview_recording(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    upload = request.files.get("recording")
    if not upload:
        return json_error("recording file is required")
    upload_folder = current_app.config.get("UPLOAD_FOLDER", "instance/uploads")
    recording_dir = Path(upload_folder) / "ai_interview_recordings"
    recording_dir.mkdir(parents=True, exist_ok=True)
    filename = f"{interview.id}-{uuid.uuid4().hex}.webm"
    path = recording_dir / filename
    upload.save(path)
    interview.recording_path = str(path)
    db.session.commit()
    return jsonify({"ok": True})


@api.get("/candidate/interviews/ai/<interview_id>/messages")
def get_ai_interview_candidate_messages(interview_id: str):
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    return jsonify({"messages": interview.admin_messages or []})

@api.post("/candidate/interviews/ai/<interview_id>/complete")
def complete_ai_interview(interview_id: str):
    """Finalize interview and trigger AI summary generation."""
    interview = _get_candidate_interview(interview_id)
    if not interview:
        return json_error("Interview not found", 404)
    if interview.status in ("completed", "reviewed"):
        return jsonify({"interview": ai_interview_to_dict(interview), "message": "Interview already completed."})
    if interview.status != "in_progress":
        return json_error("Interview cannot be completed from status: " + interview.status, 400)

    interview.status = "completed"
    interview.completed_at = utcnow()
    if interview.started_at:
        interview.total_duration_seconds = duration_seconds(interview.started_at, interview.completed_at)

    db.session.commit()

    try:
        generate_interview_summary(interview)
        db.session.commit()
    except Exception as exc:
        current_app.logger.warning(f"Summary generation failed for interview {interview_id}: {exc}")

    create_audit("ai_interview.completed", "ai_interview", interview_id, g.user)
    return jsonify({"interview": ai_interview_to_dict(interview), "message": "Interview completed. Your responses are being analyzed."})
